import{_ as e,o as t,c as l,a2 as o}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"Version 2.0.0.1 Released","description":"","frontmatter":{},"headers":[],"relativePath":"change-log/release/version-2.0.0.1-released.md","filePath":"change-log/release/version-2.0.0.1-released.md"}'),r={name:"change-log/release/version-2.0.0.1-released.md"};function a(n,i,s,d,c,p){return t(),l("div",null,[...i[0]||(i[0]=[o('<h1 id="version-2-0-0-1-released" tabindex="-1">Version 2.0.0.1 Released <a class="header-anchor" href="#version-2-0-0-1-released" aria-label="Permalink to &quot;Version 2.0.0.1 Released&quot;">​</a></h1><h2 id="version-2-0-0-1-released-1" tabindex="-1">Version 2.0.0.1 Released <a class="header-anchor" href="#version-2-0-0-1-released-1" aria-label="Permalink to &quot;Version 2.0.0.1 Released&quot;">​</a></h2><p><strong>Date: 24th Feb 2026</strong></p><p><strong>Maintenance Release: Option Chain Analytics, Nubra Broker Integration, WebSocket Stability &amp; Infrastructure Hardening</strong></p><p>This is a maintenance release featuring <strong>314 commits</strong> (excluding auto-builds) from <strong>16 contributors</strong>, focused on new analytical tools (Option Greeks, GEX Dashboard, Volatility Surface), full Nubra broker integration, comprehensive WebSocket stability fixes across all brokers, NSE/BSE index symbol normalization, Docker infrastructure improvements, and CI/CD pipeline establishment.</p><hr><h4 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h4><ul><li><strong>Option Chain &amp; Analytics Suite</strong> - Option Chain page with PlaceOrder dialog, Option Greeks (IV/Delta/Theta/Vega/Gamma), GEX Dashboard, IV Smile, OI Profile, 3D Volatility Surface, ATM Straddle Chart, OI Tracker, Max Pain</li><li><strong>Nubra Broker Integration</strong> - Complete broker integration including orders, positions, holdings, funds, historical data, WebSocket streaming, and master contracts</li><li><strong>WebSocket Stability Overhaul</strong> - File descriptor leak fixes, health checks, reconnection logic, and resource cleanup across all broker streaming adapters</li><li><strong>NSE/BSE Index Symbol Normalization</strong> - Standardized index symbol mappings across Zerodha, Dhan, Fyers, Angel, Upstox, Shoonya, Flattrade, and Nubra</li><li><strong>System Health Monitor</strong> - Real-time health monitoring dashboard with process metrics and chart visualization</li><li><strong>CI/CD Pipeline</strong> - Comprehensive CI/CD with Ruff linting, Docker Hub builds, Dependabot, and automated frontend builds</li><li><strong>Docker &amp; Installation</strong> - Multi-instance installer, Docker Desktop scripts (Windows/macOS/Linux), automatic migrations, SSL support</li><li><strong>Sandbox Enhancements</strong> - Realistic LIMIT/SL order fills, WebSocket auto-upgrade, P&amp;L calculation fixes</li><li><strong>Batched Basket Orders</strong> - Concurrent basket order execution for all brokers with eventlet compatibility</li></ul><hr><h4 id="new-features" tabindex="-1">New Features <a class="header-anchor" href="#new-features" aria-label="Permalink to &quot;New Features&quot;">​</a></h4><p><strong>Option Chain &amp; Analytics Tools</strong></p><ul><li>Add Option Chain page with real-time WebSocket LTP/Bid/Ask data</li><li>Add PlaceOrder dialog with Buy/Sell buttons directly from Option Chain</li><li>Add Option Greeks page with IV/Delta/Theta/Vega/Gamma charts and Tools hub</li><li>Add GEX Dashboard, IV Smile, and OI Profile analytical tools</li><li>Add 3D Volatility Surface analytical tool</li><li>Add Dynamic ATM Straddle Chart analytical tool</li><li>Add OI Tracker and Max Pain analytical tools</li><li>Add Option Chain link to main navbar</li><li>REST API fallback for market depth in PlaceOrderDialog</li><li>Round WebSocket LTP/Bid/Ask to tick size in Option Chain</li><li>Display bid/ask quantities in option chain page</li></ul><p><strong>System Health Monitor</strong></p><ul><li>Add system health monitoring dashboard with real-time metrics</li><li>Add migration for health metrics process details</li><li>Enhance HealthMonitor with dynamic chart intervals and tab visibility handling</li><li>Display IST time in Health Monitor chart crosshair and axis</li></ul><p><strong>Historify Enhancements</strong></p><ul><li>Add scheduler for automated data downloads</li><li>Add symbol validation and bidirectional incremental download</li><li>Add time picker with AM/PM for daily schedules</li><li>Add bulk delete for historical data and watchlist</li><li>Default schedule type to Daily</li><li>Clarify incremental download behavior in scheduler UI</li></ul><p><strong>Flow Editor Improvements</strong></p><ul><li>Add Order Status node configuration and executor</li><li>Add price type field to options order node</li><li>Fetch options lot sizes from master contract database</li><li>Cap exponent size in flow math expressions to prevent DoS</li><li>Fix OptionSymbol, Multiquotes, and OpenPosition issues</li><li>Fix Smart Order now supports negative position sizes</li><li>Fix modify order not reading price/quantity fields</li><li>Correct weekday selection in flow editor schedule node</li><li>Correct parameter names for get_option_chain in flow editor</li><li>Resolve handle jittering and add neon glow effects</li><li>Improve node connection UX</li></ul><p><strong>WebSocket Enhancements</strong></p><ul><li>Add 50-level depth support with correct symbol format</li><li>Add broker-dependent depth level test pages</li><li>Add bulk subscription support for WebSocket proxy</li><li>Add REST API fallback for shared WebSocket provider</li><li>Add centralized useLiveQuote hook for real-time market data</li><li>Add greeks WebSocket channel for Nubra OI data</li><li>Shared WebSocket provider frontend update</li></ul><p><strong>Sandbox Enhancements</strong></p><ul><li>Realistic LIMIT order fill pricing in sandbox execution engine</li><li>Marketable LIMIT orders fill at LTP with retry logic</li><li>Immediate execution for SL/SL-M orders when trigger already met</li><li>Make sandbox engine actively subscribe to WebSocket market data (headless)</li><li>Auto-upgrade from polling to WebSocket when proxy becomes healthy</li><li>Add CSV export functionality to sandbox My P&amp;L page</li><li>Add special session support with custom exchange timings</li><li>Correct P&amp;L calculation for positions to match Zerodha</li></ul><p><strong>Basket Orders</strong></p><ul><li>Batched concurrent basket order execution for all brokers with eventlet compatibility</li><li>Batched concurrent basket order execution for Shoonya broker</li><li>Handle Shoonya failed orders and batch execution errors</li></ul><p><strong>Toast &amp; Notification System</strong></p><ul><li>Add toast notification control system with category-based filtering</li><li>Add Top Center and Bottom Center toast positions</li><li>Enhance position closing notifications with toast messages</li></ul><p><strong>Infrastructure &amp; Docker</strong></p><ul><li>Add comprehensive CI/CD pipeline with Ruff linting and Docker Hub builds</li><li>Add multi-instance custom SSL installer and documentation</li><li>Add Docker run scripts for Windows and macOS/Linux</li><li>Make Docker scripts standalone (download and run)</li><li>Add installation script with broker configuration and XTS validation</li><li>Automate frontend build within Dockerfile</li><li>Robust Docker healthcheck using backend-only endpoint</li><li>Add automatic migrations on container startup</li><li>Add strategies directory mount and log directory mount for Docker Desktop</li><li>Show documentation URL after setup</li><li>Add thread limiting to Docker Hub runner scripts and multi-instance installer</li></ul><p><strong>Other Features</strong></p><ul><li>Add FAQ page with accordion-based Q&amp;A sections</li><li>Add carry-forward position PnL tracking in PnL tracker</li><li>Smart master contract download with configurable cutoff time</li><li>Show data subscription alert for Zerodha and Dhan on broker select page</li><li>Enhance database path configuration for instance isolation</li><li>Add backtesting and plotting scripts for RELIANCE 5-Minute data</li><li>Refactor BrokerSelect component to filter and display only enabled brokers</li><li>Accessibility: aria-label and title to icon-only buttons in admin pages</li><li>Accessibility: aria-label to inline edit inputs</li></ul><hr><h4 id="broker-specific-changes" tabindex="-1">Broker-Specific Changes <a class="header-anchor" href="#broker-specific-changes" aria-label="Permalink to &quot;Broker-Specific Changes&quot;">​</a></h4><p><strong>Nubra (New Broker Integration)</strong></p><ul><li><strong>Full broker integration</strong> - Complete implementation from scratch</li><li>Master Contract: Symbol format expiry fixed, common index symbol updated</li><li>Orders: Place market order, limit order, smart order, modify order, cancel order, cancel all orders</li><li>Position Book and Close All Position API</li><li>Orderbook initial commit with SL and SL-M order support</li><li>SL-M fix in orderbook</li><li>Holdings: Average price fixed</li><li>Tradebook and Holdings updated</li><li>Quotes: NSE, NFO, BSE quotes and depth API updated</li><li>Funds: Converted paise to rupees</li><li>Margin Calculator API updated</li><li>Multiquotes updated</li><li>Historical API: Update, chunking method updated, F&amp;O data updated, removed unsupported segments</li><li>WebSocket: Full implementation with rate limit compliance (429 handling + throttling), resource management and thread safety hardening</li><li>Greeks WebSocket channel for OI data</li><li>Normalized NSE and BSE index symbols</li><li>Plugin JSON updated</li><li>Added to all broker lists across install scripts and docs</li></ul><p><strong>Zerodha</strong></p><ul><li>File descriptor leak fix in WebSocket adapter</li><li>Comprehensive NSE and BSE index symbol mappings added</li><li>Redundant BSE index mappings removed</li><li>Normalize NSE_INDEX and BSE_INDEX symbols</li></ul><p><strong>Dhan</strong></p><ul><li>File descriptor leak fix in streaming module</li><li>Centralize teardown logic in adapter</li><li>Normalize NSE_INDEX and BSE_INDEX symbols to Tradeboard standard format</li><li>Error handling for inactive dataAPI subscription</li><li>Show live LTP for closed positions</li><li>Enrich positions with LTP from marketfeed API</li><li>Use multiquotes service for position LTP enrichment</li><li>Show symbol details in telegram alert for individual position close</li><li>Add missing expiryCode to intraday and daily chart requests</li><li>Correct WebSocket depth levels — only Dhan supports 20-depth</li><li>Data subscription alert on broker select page</li></ul><p><strong>Fyers</strong></p><ul><li>File descriptor leak fix in streaming adapters</li><li>Add auto-reconnect to HSM WebSocket</li><li>Add reconnection and health check to HSM WebSocket</li><li>Normalize NSE_INDEX and BSE_INDEX symbols to Tradeboard standard format</li><li>Remove BSE prefix fallback for unmapped BSE_INDEX symbols</li><li>Switch MCX and CDS master contracts from CSV to JSON format</li><li>Fix NAN issue in Total P&amp;L (numeric rounding instead of string formatting)</li></ul><p><strong>Angel</strong></p><ul><li>File descriptor leak fix and health check for WebSocket</li><li>Normalize NSE_INDEX and BSE_INDEX symbols from name column</li><li>Common Index (NSE &amp; BSE) symbols update</li></ul><p><strong>Flattrade</strong></p><ul><li>File descriptor leak fix in streaming adapters</li><li>Address race conditions and thread cleanup issues in streaming</li><li>Comprehensive NSE_INDEX and BSE_INDEX symbol mappings added</li></ul><p><strong>Shoonya</strong></p><ul><li>Batched concurrent basket order execution</li><li>Handle failed orders and batch execution errors</li><li>Comprehensive NSE_INDEX symbol mappings added</li></ul><p><strong>Upstox</strong></p><ul><li>File descriptor leak prevention in streaming</li><li>NSE_INDEX and BSE_INDEX symbol mappings added</li></ul><p><strong>Groww</strong></p><ul><li>File descriptor leak fix in streaming module</li><li>Optimize streaming and master contract download</li><li>Update auth to use checksum-based flow instead of TOTP</li></ul><p><strong>Kotak</strong></p><ul><li>Option chain LTP streaming fix — subscribe both depth and LTP streams</li></ul><p><strong>AliceBlue</strong></p><ul><li>Prepend date to tradebook Filltime to fix Invalid Date display</li></ul><p><strong>Zebu</strong></p><ul><li>Broker data issues fix (2 fixes)</li></ul><hr><h4 id="bug-fixes" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h4><p><strong>WebSocket &amp; Streaming</strong></p><ul><li>Resolve critical file descriptor leaks in websocket_proxy</li><li>Improve resource cleanup and monitoring in websocket_proxy</li><li>Prevent event loop leak when WebSocket thread doesn&#39;t terminate</li><li>Fix asyncio.run() error when running with eventlet in production</li><li>Call _resubscribe_all() on PONG-based authentication</li><li>Clear _has_index flag on index channel unsubscribe</li><li>Prevent stale OHLCV quotes for index-only subscriptions</li><li>Clean up quote subscription on unsubscribe and log subscription failures</li><li>Prevent 429 rate limiting by using batch multiquotes instead of individual quote calls</li><li>Resolve WebSocket market data not showing and reduce API polling</li><li>Resolve stale auth cache causing 403 errors in WebSocket proxy</li><li>Clear all caches in WebSocket proxy cache invalidation handler</li><li>Remove noisy debug logging from WebSocket session helper</li><li>Correct WebSocket depth levels — only Dhan supports 20-depth</li></ul><p><strong>Frontend &amp; UI</strong></p><ul><li>React #185 infinite loop fix in useOptionChainLive</li><li>Remove usePageVisibility to prevent React error #185 infinite loop</li><li>Option Chain table layout stability</li><li>Option Chain performance and PlaceOrderDialog improvements</li><li>PlaceOrderDialog: remove duplicate toast and symbol display</li><li>PlaceOrder dialog: API endpoint, response handling, REST fallback</li><li>Price field floating point precision issue</li><li>Replace Radix Checkbox with custom visual to prevent infinite loop</li><li>Update day selection UI for better accessibility and interaction</li><li>Correct Latency Monitor link in dashboard Quick Access</li><li>Permission status colors in analyzer mode (Profile page)</li><li>Show real API key in TradingView and GoCharting webhook JSON</li><li>Add error display in Search component for failed API calls</li><li>Add toast category and HTTP status differentiation in Search error handling</li><li>Use correct Holiday property in aria-label to fix TypeScript build</li><li>Remove console.log from frontend</li><li>Fix Console Error: 401 and &quot;Invalid session&quot; error</li><li>Enhance P&amp;L calculations for live price updates in useLivePrice hook</li><li>Preserve greeks OI across orderbook updates</li><li>Fix F&amp;O filter performance by extracting underlying from Tradeboard symbol format</li></ul><p><strong>Orders &amp; Positions</strong></p><ul><li>Count only positions with non-zero quantity as &quot;open&quot;</li><li>Replace ThreadPoolExecutor with sequential processing in optionsmultiorder</li><li>Auto-detect stuck master contract downloads and enable Force Download</li><li>Master contract status API response format for React frontend</li><li>Use correct exchange mapping for index vs stock underlyings</li><li>Telegram alerts on close positions</li><li>Show symbol details in telegram alert for individual position close</li><li>Auto-initialize analyzer funds on order placement to prevent &#39;Funds not initialized&#39; error</li></ul><p><strong>Backend &amp; Server</strong></p><ul><li>Prevent database errors on fresh installation startup</li><li>Clear all auth caches on login to prevent stale token 401 errors</li><li>Initialize Python strategy scheduler at app startup</li><li>Use local time (IST) instead of UTC for flow execution logs</li><li>Increase strategy memory limit from 512MB to 1GB</li><li>Resolve route conflict between Flask and React (health endpoint)</li><li>Handle potential exception when retrieving swap memory metrics</li><li>Remove excessive debug logging in expiry service</li><li>Implement rate limiting for broker history API requests</li><li>Add rate limiting to straddle history calls (3 req/sec)</li><li>Fix FAQ route to serve React app instead of missing Jinja2 template</li><li>Python strategy editor keyboard save (Ctrl+S) losing recent edits</li></ul><p><strong>Docker &amp; Installation</strong></p><ul><li>Prevent RLIMIT_NPROC exhaustion in Docker and native installs</li><li>Increase RLIMIT_NPROC from 64 to 256 for multi-container deployments</li><li>Add LLVMLITE_TMPDIR to avoid noexec /tmp issues</li><li>Auto-configure LLVMLITE/NUMBA paths for hardened Linux servers</li><li>Resolve Gunicorn worker temp file error</li><li>Add dynamic shm_size based on system RAM (Windows and Linux)</li><li>Add tmp directory for master contract downloads</li><li>Increase proxy buffer size (nginx) for large auth headers</li><li>Preserve .env during updates to prevent password invalidation</li><li>Preserve custom CORS and CSP domains during updates and in install-docker.sh</li><li>Use comma-separated CORS origins as expected by Flask-CORS</li><li>Fix Windows batch script infinite loop and curl alias</li><li>Fix REDIRECT_URL broker placeholder replacement</li><li>Replace fragile sed CSP_CONNECT_SRC logic with delete-and-append in Docker install scripts</li><li>Add thread limiting env vars to multi-instance installer</li><li>Add Docker support for numba/scipy dependencies in trading strategies</li><li>Add numba/scipy support to production and remaining installation scripts</li><li>Increase Gunicorn timeout for master contract database initialization and processing</li><li>Increase systemd timeout and gunicorn worker timeout</li><li>Proper TypeScript configuration for production and test environments</li><li>Skip docker-build for fork PRs</li><li>Use git add -f for ignored frontend/dist in CI</li></ul><hr><h4 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h4><ul><li>Upgrade Pillow to 12.1.1 (CVE security fix)</li><li>Upgrade pip to 26.0.1 in uv.lock (CVE-2026-1703)</li><li>Upgrade cryptography to 46.0.5 for ECDSA/ECDH subgroup validation vulnerability</li><li>Upgrade axios to 1.13.5 (DoS via <strong>proto</strong>) and bump cffi to 2.0.0</li><li>Upgrade protobuf to 6.33.5</li><li>Override lodash-es to 4.17.23 for security patch</li><li>Cap exponent size in flow math expressions to prevent DoS</li><li>pyproject security fix</li></ul><hr><h4 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h4><ul><li>Implement useMarketData options and prevent WebSocket zombie connections</li><li>Reduce WebSocket execution engine startup log noise</li><li>Reduce Python strategy startup log noise</li><li>Change logging level from info to debug for various components</li><li>Remove unnecessary logging for market holiday checks</li><li>Increase httpx connection pool and Gunicorn workers (reverted to 1 worker for memory)</li><li>Searchable underlying selector, filter test symbols, reduce log noise</li></ul><hr><h4 id="refactoring-code-quality" tabindex="-1">Refactoring &amp; Code Quality <a class="header-anchor" href="#refactoring-code-quality" aria-label="Permalink to &quot;Refactoring &amp; Code Quality&quot;">​</a></h4><ul><li>Remove Jinja2 frontend assets and legacy files</li><li>Remove dead Jinja2 routes migrated to React</li><li>Rename Flow Workflows to Flow Editor</li><li>Apply Ruff formatting to Python codebase</li><li>Stop tracking frontend/dist (CI/CD builds it)</li><li>Replace logger.error with logger.exception in except blocks</li><li>Add type hints to helper functions in restx_api/ticker.py</li><li>Refine type hints for validate_and_adjust_date_range</li><li>Remove algomirror folder</li><li>Remove .claude/settings.local.json from tracking</li></ul><hr><h4 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h4><ul><li>Comprehensive new broker integration guide with WebSocket proxy registration</li><li>Comprehensive cache architecture audit (28+ caches)</li><li>Update design docs and PRDs to reflect codebase changes since Jan 2026</li><li>Broker API compatibility audit report</li><li>WebSocket depth level compatibility added to broker audit</li><li>WebSocket frontend management audit and integration guidelines</li><li>Strategy Risk Management &amp; Position Tracking PRD</li><li>CI/CD and security audit report</li><li>Docker resource configuration for Python strategies</li><li>Docker Hub README</li><li>Multi-instance Docker guide and update mode documentation</li><li>Desktop Docker installation instructions</li><li>Add Plotly as an interactive charting library for options analytics</li><li>NSE_INDEX and BSE_INDEX symbol normalization test script</li><li>Update CLAUDE.md for frontend/dist CI/CD changes</li><li>Update install scripts with informative build messages</li></ul><hr><h4 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h4><p><strong>Python</strong></p><ul><li>Bump the python-minor group with 69 updates</li><li>pytest 8.4.2 → 9.0.2</li><li>Pillow → 12.1.1</li><li>cryptography → 46.0.5</li><li>axios → 1.13.5</li><li>cffi → 2.0.0</li><li>protobuf → 6.33.5</li><li>pip → 26.0.1</li><li>lodash-es → 4.17.23 (override)</li><li>numpy pinned to &gt;=2.0,&lt;2.4 (numba compatibility)</li><li>logistro → 2.0.1</li><li>Docker: gunicorn eventlet version update</li></ul><p><strong>Frontend</strong></p><ul><li>jsdom 24.1.3 → 27.4.0</li><li>Frontend deps group bump</li><li>npm-root group with 3 updates</li></ul><p><strong>CI/CD Actions</strong></p><ul><li>actions/checkout 4 → 6</li><li>actions/setup-node 4 → 6</li><li>astral-sh/setup-uv 3 → 7</li><li>github/codeql-action 3 → 4</li><li>actions/upload-artifact 4 → 6</li></ul><hr><h4 id="infrastructure" tabindex="-1">Infrastructure <a class="header-anchor" href="#infrastructure" aria-label="Permalink to &quot;Infrastructure&quot;">​</a></h4><ul><li>Comprehensive CI/CD pipeline with Ruff linting, Docker Hub push, frontend auto-build</li><li>Backend-lint configured to pass with pre-existing warnings</li><li>Repair CI after Jinja2 cleanup</li><li>Docker Hub build triggers</li><li>Auto-build frontend dist via GitHub Actions</li><li>Add .claude settings files to .gitignore</li></ul><hr><h4 id="contributors" tabindex="-1">Contributors <a class="header-anchor" href="#contributors" aria-label="Permalink to &quot;Contributors&quot;">​</a></h4><p>Special thanks to all contributors who made this release possible:</p><ul><li>@Kalaiviswa (kalaivani) - WebSocket stability, Basket orders, Flow Editor, Index symbol normalization</li><li>@rochronaldo (roch ronaldo) - Nubra broker integration</li><li>@AravindGandavadi - Docker installation, CORS fixes, TypeScript configs</li><li>@uttamsingh - Python strategy editor fix</li><li>@kiranjv - Zebu broker data fixes</li><li>@jabez4jc - Gunicorn timeout fixes</li><li>@SubhAushSingh - Type hints improvements</li><li>@Sadhanandhann - Expiry service and Dhan chart fixes</li><li>@OriolMorros (Oriol Morros Vilaseca) - Accessibility and Search error handling</li><li>@AlexZhonn - Frontend cleanup</li><li>@slegarraga - Accessibility improvements</li><li>@PremParkash - App.py update</li><li>@HarshPrajapati - Logger refactoring</li></ul><hr><hr><h4 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h4><ul><li><strong>Repository</strong>: <a href="https://github.com/wesoftcorp/tradeboard-docs" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs</a></li><li><strong>Documentation</strong>: <a href="https://docs.algo.wesoftcorp.com" target="_blank" rel="noreferrer">https://docs.algo.wesoftcorp.com</a></li><li><strong>Discord</strong>: <a href="https://www.tradeboard.in/discord" target="_blank" rel="noreferrer">https://www.tradeboard.in/discord</a></li></ul><hr>',100)])])}const g=e(r,[["render",a]]);export{h as __pageData,g as default};
